protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Preserve "Discriminator" so existing 500K documents remain queryable and
        // direct SQL queries using c.Discriminator continue to work.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 no longer embeds the discriminator in the JSON id property.
        // Preserve the old "Product|123" format so existing documents are still
        // accessible via FindAsync / point-reads.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // REMOVED: HasIndex() — EF Core 9 Cosmos provider now throws at startup
    // for HasIndex calls. Manage indexing via the Azure Portal or IaC instead.
}

